cat > src/title.mjs <<'JS'
const MAX = 40;

export const headerTitle = (name) => {
  const clean = name.trim();
  return clean.length > MAX ? `${clean.slice(0, MAX - 1)}…` : clean;
};
JS
cat > test/title-long.test.mjs <<'JS'
import { test } from "node:test";
import assert from "node:assert/strict";
import { headerTitle } from "../src/title.mjs";

test("a name longer than 40 characters is cut with an ellipsis", () => {
  const title = headerTitle("Department of Radiology and Nuclear Medicine Research");
  assert.equal(title.length, 40);
  assert.ok(title.endsWith("…"));
});
